const planId = location.pathname.split("/").pop();
let currentPlan = null;

function parseJsonSafe(res) {
  return res.json().catch(() => ({}));
}

function escapeText(value) {
  return String(value == null ? "" : value).replace(/[&<>"]/g, (ch) => {
    if (ch === "&") return "&amp;";
    if (ch === "<") return "&lt;";
    if (ch === ">") return "&gt;";
    return "&quot;";
  });
}

function toLocalDate(value) {
  const date = value ? new Date(`${value}T00:00:00`) : new Date();
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

function getTripStatus(plan) {
  const today = toLocalDate();
  const start = toLocalDate(plan.startDate);
  const end = toLocalDate(plan.endDate || plan.startDate);
  const dayMs = 24 * 60 * 60 * 1000;
  const untilStart = Math.round((start - today) / dayMs);
  const sinceStart = Math.round((today - start) / dayMs) + 1;

  if (untilStart > 0) {
    return { label: `D-${untilStart}`, detail: `출발까지 ${untilStart}일 남았습니다.` };
  }
  if (today <= end) {
    return { label: "여행 중", detail: `${sinceStart}일차 여행 중입니다.` };
  }
  return { label: "완료", detail: "이미 종료된 여행입니다." };
}

function tripStatusMode(plan) {
  const status = getTripStatus(plan);
  if (status.label.startsWith("D-")) return "upcoming";
  if (status.label === "여행 중") return "active";
  if (status.label === "완료") return "completed";
  return "unknown";
}

function actionRunwayItems(plan) {
  const mode = tripStatusMode(plan);
  if (mode === "active") {
    return {
      title: "오늘 여행 런웨이",
      detail: "오늘 확인할 브리핑, 현황, 예산을 먼저 열어보세요.",
      items: [
        { label: "오늘 브리핑", buttonId: "briefButton", hint: "일정과 이동을 빠르게 확인" },
        { label: "다음 액션", buttonId: "nextActionButton", hint: "지금 바로 할 일 확인" },
        { label: "오늘 예산", buttonId: "dailyBudgetButton", hint: "예산 페이스 확인" },
      ],
    };
  }
  if (mode === "completed") {
    return {
      title: "여행 정리 런웨이",
      detail: "회고, 지출, 메모를 정리해 다음 여행 자산으로 남기세요.",
      items: [
        { label: "여행 회고", buttonId: "recapButton", hint: "좋았던 점과 개선점 정리" },
        { label: "지출 보기", buttonId: "expenseListButton", hint: "누적 지출 확인" },
        { label: "메모팩", buttonId: "memoPackButton", hint: "개인 메모 포함 파일 저장" },
      ],
    };
  }
  return {
    title: "출발 준비 런웨이",
    detail: `${plan.destination || "이번 여행"} 출발 전 준비도와 짐, 공유 자료를 먼저 확인하세요.`,
    items: [
      { label: "준비도", buttonId: "readinessButton", hint: "빠진 준비 항목 확인" },
      { label: "짐싸기", buttonId: "packingButton", hint: "개인 짐 목록 확인" },
      { label: "출발팩", buttonId: "departurePackButton", hint: "출발 전 공유 파일 저장" },
    ],
  };
}

function runwayChecklistProgressText(values, total) {
  const checked = Array.isArray(values) ? values.filter(Boolean).length : 0;
  return total > 0 && checked === total ? `${checked}/${total} 모두 완료` : `${checked}/${total} 완료`;
}

function runwayChecklistProgressPercent(checked, total) {
  return total ? Math.round((checked / total) * 100) : 0;
}

function runwayChecklistPhaseText(checked, total) {
  if (total > 0 && checked === total) return "완료";
  if (checked === 0) return "시작 전";
  if (total > 1 && checked === total - 1) return "마무리 단계";
  return "진행 중";
}

function runwayChecklistPhaseKey(checked, total) {
  if (total > 0 && checked === total) return "complete";
  if (checked === 0) return "start";
  if (total > 1 && checked === total - 1) return "finish";
  return "progress";
}

function runwayChecklistPhaseHint(checked, total) {
  if (total > 0 && checked === total) return "추천 런웨이를 모두 처리했습니다.";
  if (checked === 0) return "첫 추천 액션부터 시작하세요.";
  if (total > 1 && checked === total - 1) return "마지막 추천 액션만 남았습니다.";
  return "다음 추천 액션을 이어서 처리하세요.";
}

function runwayChecklistProgressSummaryText(values, total) {
  const checked = Array.isArray(values) ? values.filter(Boolean).length : 0;
  return `${runwayChecklistProgressText(values, total)} · ${runwayChecklistProgressPercent(checked, total)}% · ${runwayChecklistPhaseText(checked, total)}`;
}

function runwayChecklistNextOrderText(values, total) {
  const nextIndex = runwayChecklistNextIndex(values);
  return nextIndex === -1 ? "완료" : `${nextIndex + 1}/${total}`;
}

function runwayChecklistNextIndex(values) {
  return Array.isArray(values) ? values.findIndex((value) => !value) : -1;
}

function runwayChecklistNextText(config, values) {
  const nextIndex = runwayChecklistNextIndex(values);
  if (nextIndex === -1) return "모든 추천 액션 완료";
  const item = config.items[nextIndex];
  return item ? `${nextIndex + 1}. ${item.label}` : "남은 액션 확인";
}

function runwayChecklistRemainingText(config, values) {
  const remaining = config.items.filter((_item, index) => !values[index]).length;
  return remaining ? `남은 ${remaining}개` : "남은 액션 없음";
}

function formatRunwayChecklistUpdatedAt(value) {
  if (!value) return "로컬 저장 전";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "로컬 저장 전";
  const today = new Date();
  const sameDay = date.getFullYear() === today.getFullYear()
    && date.getMonth() === today.getMonth()
    && date.getDate() === today.getDate();
  const dayLabel = sameDay
    ? "오늘"
    : `${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
  return `${dayLabel} ${String(date.getHours()).padStart(2, "0")}:${String(date.getMinutes()).padStart(2, "0")} 업데이트`;
}

function currentRunwayChecklistValues(runway, config) {
  return config.items.map((_item, index) => {
    const checkbox = runway.querySelector(`[data-runway-check="${index}"]`);
    return Boolean(checkbox?.checked);
  });
}

function buildRunwayChecklistShareText(plan, config, checklistValues, updatedAt = "") {
  const status = getTripStatus(plan);
  const nextIndex = runwayChecklistNextIndex(checklistValues);
  return [
    "Travel Planner 런웨이 체크리스트",
    `- 플랜: ${plan.destination || "목적지 미정"} 여행`,
    `- 기간: ${plan.startDate || ""} ~ ${plan.endDate || ""}`,
    `- 상태: ${status.label} · ${status.detail}`,
    `- 초점: ${config.title}`,
    `- 안내: ${config.detail}`,
    `- 체크 진행률: ${runwayChecklistProgressSummaryText(checklistValues, config.items.length)}`,
    `- 단계 힌트: ${runwayChecklistPhaseHint(checklistValues.filter(Boolean).length, config.items.length)}`,
    `- 완료 액션 수: ${checklistValues.filter(Boolean).length}개`,
    `- 남은 액션 수: ${runwayChecklistRemainingText(config, checklistValues)}`,
    `- 다음 액션: ${runwayChecklistNextText(config, checklistValues)}`,
    `- 다음 순번: ${runwayChecklistNextOrderText(checklistValues, config.items.length)}`,
    `- 업데이트: ${formatRunwayChecklistUpdatedAt(updatedAt)}`,
    "- 저장 범위: 이 브라우저에만 저장",
    ...config.items.map((item, index) => {
      const mark = checklistValues[index] ? "[x]" : "[ ]";
      const relationLabel = `${runwayAnchorRelationLabel(index, nextIndex)} · ${checklistValues[index] ? "완료" : "미완료"}`;
      return `${mark} ${index + 1}. ${item.label} (${relationLabel}): ${item.hint} · 링크: ${actionRunwayUrl(index)}`;
    }),
    nextIndex === -1 ? `- 완료 런웨이 링크: ${actionRunwayUrl()}` : `- 체크리스트 링크: ${actionRunwayUrl()}`,
  ].filter(Boolean).join("\n");
}

function buildRunwayRemainingActionsText(plan, config, checklistValues, updatedAt = "") {
  const status = getTripStatus(plan);
  const nextIndex = runwayChecklistNextIndex(checklistValues);
  const remaining = config.items
    .map((item, index) => ({ item, index }))
    .filter(({ index }) => !checklistValues[index]);
  return [
    "Travel Planner 남은 런웨이 액션",
    `- 플랜: ${plan.destination || "목적지 미정"} 여행`,
    `- 상태: ${status.label} · ${status.detail}`,
    `- 체크 진행률: ${runwayChecklistProgressSummaryText(checklistValues, config.items.length)}`,
    `- 단계 힌트: ${runwayChecklistPhaseHint(checklistValues.filter(Boolean).length, config.items.length)}`,
    `- 남은 액션 수: ${runwayChecklistRemainingText(config, checklistValues)}`,
    `- 다음 액션: ${runwayChecklistNextText(config, checklistValues)}`,
    `- 다음 순번: ${runwayChecklistNextOrderText(checklistValues, config.items.length)}`,
    `- 체크 업데이트: ${formatRunwayChecklistUpdatedAt(updatedAt)}`,
    "- 저장 범위: 이 브라우저에만 저장",
    remaining.length ? "- 남은 액션:" : "- 남은 액션: 없음",
    remaining.length ? "" : "- 완료 안내: 추천 런웨이를 모두 처리했습니다.",
    ...remaining.map(({ item, index }) => `${index + 1}. ${item.label} (${runwayAnchorRelationLabel(index, nextIndex)} · 미완료): ${item.hint} · 링크: ${actionRunwayUrl(index)}`),
    `- 런웨이 링크: ${actionRunwayUrl()}`,
  ].filter(Boolean).join("\n");
}

