function setRunwayChecklistFeedback(runway, text, tone = "") {
  const feedback = runway.querySelector("[data-runway-checklist-feedback]");
  if (feedback) {
    feedback.textContent = text;
    feedback.classList.toggle("is-link-arrival", tone === "link");
  }
}

function setRunwayChecklistUpdatedAt(runway, updatedAt) {
  const updated = runway.querySelector("[data-runway-checklist-updated]");
  if (updated) {
    updated.textContent = formatRunwayChecklistUpdatedAt(updatedAt);
    updated.classList.toggle("is-pending", !updatedAt);
  }
}

function runwayAnchorRelationLabel(anchorIndex, nextIndex) {
  if (nextIndex === -1) return "완료 런웨이";
  return anchorIndex === nextIndex ? "다음 액션" : "참고 액션";
}

function refreshRunwayAnchorCardState(runway, config) {
  const anchoredActionMatch = window.location.hash.match(/^#tripActionRunwayAction(\d+)$/);
  const anchoredActionIndex = anchoredActionMatch ? Number(anchoredActionMatch[1]) - 1 : -1;
  const anchoredActionCard = anchoredActionIndex >= 0 ? runway.querySelector(`[data-runway-action-card="${anchoredActionIndex}"]`) : null;
  const checklistValues = currentRunwayChecklistValues(runway, config);
  const nextIndex = runwayChecklistNextIndex(checklistValues);
  runway.classList.toggle("is-anchor-target", window.location.hash === "#tripActionRunway" || Boolean(anchoredActionCard));
  runway.querySelectorAll("[data-runway-action-card]").forEach((card) => {
    const isAnchorTarget = card === anchoredActionCard;
    const index = Number(card.dataset.runwayActionCard);
    const done = card.classList.contains("is-complete");
    const relationLabel = runwayAnchorRelationLabel(index, nextIndex);
    card.classList.toggle("is-anchor-target", isAnchorTarget);
    const rank = card.querySelector("[data-runway-action-rank]");
    if (rank) {
      rank.textContent = `${index + 1}순위${done ? " 완료" : ""}${isAnchorTarget ? ` · 링크 열림 · ${relationLabel}` : ""}`;
    }
    const target = card.querySelector("[data-runway-target]");
    if (target) {
      const baseTitle = target.dataset.runwayTargetTitle || target.title;
      const baseLabel = target.dataset.runwayTargetLabel || target.getAttribute("aria-label") || baseTitle;
      target.dataset.runwayTargetTitle = baseTitle;
      target.dataset.runwayTargetLabel = baseLabel;
      const openedPrefix = isAnchorTarget ? "링크로 열린 추천. " : "";
      const relationPrefix = isAnchorTarget ? `${relationLabel}. ` : "";
      const donePrefix = done ? "완료됨. " : "";
      target.title = `${openedPrefix}${relationPrefix}${donePrefix}${baseTitle}`;
      target.setAttribute("aria-label", `${openedPrefix}${relationPrefix}${donePrefix}${baseLabel}`);
    }
  });
  return { anchoredActionCard, anchoredActionIndex };
}

function clearRunwayLinkArrivalFeedback(runway) {
  const feedback = runway.querySelector("[data-runway-checklist-feedback]");
  if (feedback?.classList.contains("is-link-arrival")) setRunwayChecklistFeedback(runway, "");
}

async function shareActionRunwayText(button, text, url) {
  if (navigator.share) {
    try {
      await navigator.share({
        title: "Travel Planner 액션 런웨이",
        text,
        url,
      });
      return;
    } catch (err) {
      if (err?.name === "AbortError") return;
    }
  }
  await copyWithButtonFeedback(button, text, "현재 플랜 액션 런웨이를 복사했습니다.");
}

