        const examples = manifest.automation?.commandExamples || {};
        const groups = Array.isArray(manifest.automation?.commandExampleGroups) ? manifest.automation.commandExampleGroups : [];
        if (groups.length) {
          const groupedLines = groups.flatMap((group) => {
            const commands = Array.isArray(group.commands) ? group.commands : [];
            const commandLines = commands
              .filter((item) => item?.command)
              .map((item) => `- ${item.label || item.key}: ${item.command}`);
            return commandLines.length ? [`# ${group.label || group.id || "Command examples"}`, ...commandLines, ""] : [];
          });
          const groupedText = groupedLines.join("\n").trim();
          if (groupedText) return groupedText;
        }
