        const knownKeys = new Set(orderedExamples.map(([key]) => key));
        const orderedLines = orderedExamples.map(([key, label]) => examples[key] ? `${label}: ${examples[key]}` : "");
        const fallbackLines = Object.entries(examples)
          .filter(([key, value]) => value && !knownKeys.has(key))
          .sort(([left], [right]) => left.localeCompare(right))
